select do2.id, doe.id as detailId, do2.code, do2.source_id as sourceId, doe.source_detail_id as purchaseDetailId, do2.plan_delivery_date as planDeliveryDate, doe.receive_code as receiveCode, do2.is_print as isPrint, do2.receipt_status as receiptStatus, doe.receipt_status as detailReceiptStatus, do2.source_code as sourceCode, doe.sku_id as skuId, doe.sku_no as skuNo, doe.is_urgent as isUrgent, doe.product_name as productName, doe.order_qty as orderQty, doe.delivery_qty as deliveryQty, doe.gift_qty as giftQty, doe.receive_qty as receiveQty, doe.gift_receive_qty as giftReceiveQty, doe.qc_good_qty as qcGoodQty, doe.remark, do2.customer_name as customerName, do2.to_warehouse_name as toWarehouseName, do2.print_date as printDate, doe.confirm_receive_date as confirmReceiveDate, do2.create_user_name as createUserName, do2.create_time as createTime, do2.supplier_id as supplierId from delivery_order do2 inner join delivery_order_detail doe on do2.id = doe.main_id and doe.is_deleted = false where ${params.sqlMap.default} and do2.is_deleted = false
and do2.supplier_id in
#{item}
ORDER BY
${item.field} ${item.sort}
do2.plan_delivery_date ASC,do2.create_time DESC ,do2.id ASC

select do2.id, doe.id as detailId, do2.code, doe.source_detail_id as purchaseDetailId, do2.plan_delivery_date as planDeliveryDate, doe.receive_code as receiveCode, do2.is_print as isPrint, do2.receipt_status as receiptStatus, doe.receipt_status as detailReceiptStatus, do2.source_id as sourceId, do2.source_code as sourceCode, doe.sku_id as skuId, doe.sku_no as skuNo, doe.is_urgent as isUrgent, doe.product_name as productName, doe.order_qty as orderQty, doe.delivery_qty as deliveryQty, doe.gift_qty as giftQty, doe.receive_qty as receiveQty, doe.gift_receive_qty as giftReceiveQty, doe.qc_good_qty as qcGoodQty, do2.customer_name as customerName, do2.to_warehouse_name as toWarehouseName, do2.print_date as printDate, doe.confirm_receive_date as confirmReceiveDate, do2.create_user_name as createUserName, do2.create_time as createTime, do2.supplier_id as supplierId from delivery_order do2 inner join delivery_order_detail doe on do2.id = doe.main_id and doe.is_deleted = false where ${params.sqlMap.default} and do2.is_deleted = false
and do2.supplier_id in
#{item}
