do2.plan_delivery_date ASC

select do2.id, doe.id as detailId, do2.receipt_status as receiptStatus, doe.receipt_status as detailReceiptStatus, do2.code, do2.supplier_id, doe.sku_id, doe.sku_no, doe.product_name, doe.delivery_qty, doe.gift_qty from delivery_order do2 inner join delivery_order_detail doe on do2.id = doe.main_id where do2.is_deleted = false and doe.is_deleted = false and do2.id in
#{item}
